def f_trail(n):
    if n in (12,13,14,19): return REAL[n-1] + " "*20
    return "pad_%02d = %d" % (n,n)
mk('t_trail', build(f_trail))

# 2. CRLF endings, real content
mk('t_crlf', None, raw=("\r\n".join(REAL[:25])+"\r\n").encode())

# 3. tab-indented lines 12-14,19
def f_tab(n):
    if n in (12,13,14,19): return "\t\t\t" + REAL[n-1].strip()
    return "pad_%02d = %d" % (n,n)
mk('t_tab', build(f_tab))

# 4. leading VERTICAL TAB (\x0b) then real content  (str.isspace yes, C strip no)
def f_vt(n):
    if n in (12,13,14,19): return "\x0b\x0b\x0b\x0b" + REAL[n-1].strip()
    return "pad_%02d = %d" % (n,n)
mk('t_vtab', build(f_vt))

# 4b. leading FORM FEED (\x0c) -> C strips it
def f_ff(n):
    if n in (12,13,14,19): return "\x0c\x0c\x0c\x0c" + REAL[n-1].strip()
    return "pad_%02d = %d" % (n,n)
mk('t_ff', build(f_ff))

# 4c. leading NBSP (U+00A0) - not python isspace? it is not str.isspace()? actually NBSP.isspace() True
def f_nb(n):
    if n in (12,13,14,19): return "    " + REAL[n-1].strip()
    return "pad_%02d = %d" % (n,n)
mk('t_nbsp', build(f_nb))

# 5. exact-span boundary: line12 = 11 spaces + 33 chars ; line19 = 4 spaces + 6 chars
def f_span(n):
    if n == 12: return " "*11 + "X"*33
    if n == 13: return " "*12 + "Y"*40
    if n == 14: return " "*12 + "Z"*41
    if n == 19: return " "*4 + "W"*6
    return "pad_%02d = %d" % (n,n)
mk('t_span', build(f_span))

# 6. invalid UTF-8 bytes on lines 12-19
lines=[]
for n in range(1,26):
    if 12 <= n <= 19: lines.append(b"    bad_%02d = \xff\xfe + tail(%d)" % (n,n))
    else: lines.append(b"pad_%02d = %d" % (n,n))
mk('t_badutf8', None, raw=b"\n".join(lines)+b"\n")

# 7. PEP263 latin-1 cookie with latin-1 high bytes
lines=[b"# -*- coding: latin-1 -*-"]
for n in range(2,26):
    if 12 <= n <= 19: lines.append(b"    caf\xe9_%02d = na\xefve[\xfc] + t(%d)" % (n,n))
    else: lines.append(b"pad_%02d = %d" % (n,n))
mk('t_latin1', None, raw=b"\n".join(lines)+b"\n")

# 8. BOM + real content
mk('t_bom', None, raw=b"\xef\xbb\xbf"+("\n".join(REAL[:25])+"\n").encode())

# 9. whitespace-only lines 12-14,19
def f_ws(n):
    if n in (12,13,14,19): return "        "
    return "pad_%02d = %d" % (n,n)
mk('t_wsonly', build(f_ws))

# 10. 19 lines, last line short, NO trailing newline
lines=[]
for n in range(1,20):
    if n==12: lines.append("    dd = ll(mm(ii, aa.a.ss(',')))")
    elif n==19: lines.append("z=1")
    else: lines.append("pad_%02d = %d" % (n,n))
mk('t_nonl', None, raw=("\n".join(lines)).encode())

# 11. short lines everywhere (readable) -> the i_noread geometry without perms
def f_short(n): return "l%02d = %d" % (n,n)
mk('t_short', build(f_short))

